package com.ruoyi.medical.persistence;
import com.ruoyi.medical.identity.*;import com.ruoyi.medical.persistence.mapper.*;import javax.sql.DataSource;
import org.springframework.beans.factory.ObjectProvider;import org.springframework.beans.factory.annotation.*;import org.springframework.context.annotation.*;import org.springframework.boot.autoconfigure.condition.*;
/** Independent opt-in EVAL stage originals and predispatch compiler; no source, grant or fixture is seeded. */
@Configuration(proxyBeanMethods=false)
@ConditionalOnProperty(prefix="medical.formal-evaluation-execution",name="enabled",havingValue="true",matchIfMissing=false)
public class FormalEvaluationStageInputConfiguration {
 @Bean FormalEvaluationStageInputSchema formalEvaluationStageInputSchema()throws Exception{return new FormalEvaluationStageInputSchema();}
 @Bean FormalEvaluationCaseOriginals formalEvaluationCaseOriginals(DataSource d,EnterpriseAccess a,FormalEvaluationJobs j,FormalEvaluationContextPackages p,ResourceReadAuthority r,PermissionMapper m,PermissionAuthority g,PlatformMemberIdentityStatus i,PermissionSchema json,FormalEvaluationStageInputSchema s,EvaluationRuleAuthority rules,DependencyLineage lineage){return new FormalEvaluationCaseOriginals(d,a,j,p,r,m,g,i,json,s,rules,lineage);}
 @Bean FormalEvaluationStageInputPreparation formalEvaluationStageInputPreparation(DataSource d,PermissionSchema j,FormalEvaluationStageInputSchema s,FormalEvaluationJobs jobs,FormalEvaluationCaseOriginals c,FormalEvaluationContextStore contexts,FormalEvaluationContextPackages p,FormalCapabilityIdentityAuthority caps,FormalRuntimeCapabilityIdentityAuthority components,FormalEvaluationRuntimeObjects o,ObjectProvider<FormalEvaluationNodeRuntime> runtime,SourceUploadTransport t,FormalTokenizerRunner tokenizer,FormalInvocationSourceOriginals originals,DocumentReadService documents,DependencyLineage lineage,StrictComparisonPolicyService policies,EvaluationRuleAuthority rules,StrictDecimalEvidenceService decimals,SourceExactService exactSources,FormalEvaluationContextReads contextReads,TemplateApplicabilityService applicability){return new FormalEvaluationStageInputPreparation(d,j,s,jobs,c,contexts,p,caps,components,o,runtime,t,tokenizer,originals,documents,lineage,policies,rules,decimals,exactSources,contextReads,applicability);}
 @Bean FormalEvaluationStageInputObjects formalEvaluationStageInputObjects(DataSource d,PermissionSchema j,DependencyManifestSchema m,DependencyLineage l,SourceReadMapper s,ArtifactRegistryMapper a){return new FormalEvaluationStageInputObjects(d,j,m,l,s,a);}
 @Bean(name="formalEvaluationStageInputTransport") RuntimeObjectTransport transport(SourceUploadTransport t,@Value("${medical.formal-evaluation-execution.stage-input-directory}")String path)throws Exception{return new RuntimeObjectTransport(t,java.nio.file.Path.of(path),16777216);}
 @Bean FormalEvaluationCaseAuthoring formalEvaluationCaseAuthoring(EnterpriseAccess access,FormalEvaluationJobs jobs,FormalEvaluationCaseOriginals cases,FormalEvaluationStageInputSchema schema,PermissionSchema json,AgentPublicationDependencies dependencies,ArtifactRegistryMapper registry,DependencyLineage lineage,FormalEvaluationStageInputObjects objects,@Qualifier("formalEvaluationStageInputTransport")RuntimeObjectTransport transport){return new FormalEvaluationCaseAuthoring(access,jobs,cases,schema,json,dependencies,registry,lineage,objects,transport);}
 @Bean FormalEvaluationNodeInputs formalEvaluationNodeInputs(FormalEvaluationJobs jobs,FormalEvaluationExactInputObjectLedger ledger,FormalEvaluationExactInputObjectRegistration registrations,FormalEvaluationContextStore contexts,FormalEvaluationExactInputObjectDependencies dependencies,AgentExecutionPolicyAuthority policies,SourceUploadTransport transport,PermissionSchema json,FormalEvaluationContextReads contextReads,FormalEvaluationNodeInputObjectLedger planningLedger,FormalEvaluationNodeInputObjectRegistration planningRegistrations,FormalEvaluationNodeInputObjectDependencies planningDependencies,FormalEvaluationStageInputPreparation stages,FormalEvaluationStageInputObjects stageObjects,@Qualifier("formalEvaluationStageInputTransport")RuntimeObjectTransport stageTransport){return new FormalEvaluationNodeInputs(jobs,ledger,registrations,contexts,dependencies,policies,transport,json,contextReads,planningLedger,planningRegistrations,planningDependencies,stages,stageObjects,stageTransport);}
}
